// Runs once when the follow-up loop is finished. Counts what happened this run (company names for the Telegram summary).
// Nodes inside the loop run once per lead, and $(name).all() only returns the LAST run, so collect every run.
const allRuns = (name) => {
  const out = [];
  for (let r = 0; r < 1000; r++) {
    let items;
    try { items = $(name).all(0, r); } catch (e) { break; }
    if (!items || !items.length) { if (r > 0) break; else continue; }
    out.push(...items);
  }
  return out;
};
const count = (name) => allRuns(name).length;
const names = {};
try { for (const i of $('Get Leads').all()) if (i.json['Lead ID']) names[i.json['Lead ID']] = i.json.Company || ''; } catch (e) {}
const label = (id) => names[id] ? names[id] + ' (' + id + ')' : id;
const ids = (name) => [...new Set(allRuns(name).map(i => i.json['Lead ID'] || '').filter(Boolean))];
const sent = allRuns('Update Follow-up Row').map(i => label(i.json['Lead ID'] || '') + ' ' + (i.json.Stage || 'follow-up'));
const drafted = ids('Save Follow-up Draft').map(label);
return [{ json: {
  sent_count: sent.length,
  sent_list: sent.join(', '),
  drafted_count: drafted.length,
  drafted_list: drafted.join(', '),
  blocked_count: count('Log Follow-up Blocked'),
  declined_count: count('Log Follow-up Declined'),
} }];

// Approval gate for follow-ups. Looks at the lead row (not the Gmail thread).
// Drafts are written one working day before the due date so the approval is in time; sending waits for the due date.
const lead = $('Loop Over Follow-ups').item.json;
const draft = String(lead['Follow-up Draft'] || '').trim();
const approved = String(lead.Approved || '').trim();
const due = String(lead['Next Follow-up Date'] || '').slice(0, 10) <= $today.toFormat('yyyy-MM-dd');
let action = 'draft';
if (draft) {
  if (approved === 'Yes') action = due ? 'send' : 'wait';
  else if (approved === 'No') action = 'decline';
  else if (approved === 'Edit') action = 'draft';
  else action = 'wait';
}
// Who approved it: the dashboard writes a Log row (Workflow 'Dashboard', Step 'approve_followup', Reason 'by <email>').
let approver = '';
if (action === 'send') {
  let rows = [];
  try { rows = $('Read Log').all(); } catch (e) {}
  for (let k = rows.length - 1; k >= 0; k--) {
    const j = rows[k].json || {};
    if (j.Workflow === 'Dashboard' && j['Lead ID'] === lead['Lead ID'] && j.Step === 'approve_followup') { approver = String(j.Reason || '').replace(/^by\s+/, '').trim(); break; }
  }
}
return { json: {
  lead_id: lead['Lead ID'],
  fu_action: action,
  fu_previous_draft: draft,
  fu_edit_notes: approved === 'Edit' ? String(lead['Nil Notes'] || '').trim() : '',
  fu_approver: approver || 'not recorded (Approved was set in the sheet)',
} };

// Builds an RFC 2822 reply that Gmail keeps in the original thread (threadId + Re: subject + In-Reply-To/References).
// The text sent is the draft Nil approved in the Leads column "Follow-up Draft".
const meta = $input.item.json;
const headers = (meta.payload && meta.payload.headers) || [];
const msgId = (headers.find(h => String(h.name).toLowerCase() === 'message-id') || {}).value || '';
const thread = $('Get Thread').first().json;
const original = (thread.messages || [])[0] || {};
const to = original.To || $('Loop Over Follow-ups').item.json.Email;
let subject = String(original.Subject || $('Loop Over Follow-ups').item.json.Subject || '');
if (!/^re:/i.test(subject)) subject = 'Re: ' + subject;
const body = String($('Loop Over Follow-ups').item.json['Follow-up Draft'] || '');
if (!body.trim()) throw new Error('Follow-up Draft is empty for ' + $('Loop Over Follow-ups').item.json['Lead ID']);
const encSubject = '=?UTF-8?B?' + Buffer.from(subject, 'utf8').toString('base64') + '?=';
const lines = [
  'To: ' + to,
  'Subject: ' + encSubject,
  msgId ? 'In-Reply-To: ' + msgId : null,
  msgId ? 'References: ' + msgId : null,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  Buffer.from(body, 'utf8').toString('base64'),
].filter(l => l !== null);
const raw = Buffer.from(lines.join('\r\n'), 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return { json: { raw, threadId: thread.id || $('Loop Over Follow-ups').item.json['Gmail Thread ID'], to, subject, in_reply_to: msgId } };

// Plain-code check of the follow-up text before it is saved for approval (Nil's decisions of 23 Nov 2026, section 9 and 10).
// Blocked follow-ups are not saved and are written to the Log tab.
const body = String($input.item.json.output?.body || '');
const lead = $('Loop Over Follow-ups').item.json;
const settings = $('Read Settings (mail)').first().json || {};
const lang = ['turkey', 'türkiye', 'turkiye'].includes(String(lead.Country || '').trim().toLowerCase()) ? 'tr' : 'en';
const brand = /^(marka|brand)$/i.test(String(lead.Segment || '').trim());
const domainOf = (u) => String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split(':')[0].trim();
const reasons = [];
if (!body.trim()) reasons.push('Body is empty');
const words = body.trim().split(/\s+/).length;
if (words > 230) reasons.push('Too long (' + words + ' words)');
const banned = ['garanti', 'guaranteed', '%100', '100%', 'son şans', 'last chance'];
const hits = banned.filter(b => body.toLowerCase().includes(b));
if (hits.length) reasons.push('Hype wording: ' + hits.join(', '));
for (const r of nilRuleIssues(body, { lang, calendarLink: settings['Calendar Link'], ownDomain: domainOf(settings['Company Website'] || 'texprove.com') || 'texprove.com', senderName: settings['Sender Name'] })) reasons.push(r);
for (const r of sensitiveIssues(body, brand ? lead.Company : '')) reasons.push(r);

return { json: {
  ...$input.item.json,
  fu_check_status: reasons.length ? 'Blocked' : 'OK',
  fu_check_notes: reasons.join('; '),
} };

// Nil's email rules of 23 Nov 2026 (decision log sections 1, 3, 8, 9), as plain code. Same function in WF2 'Check Draft',
// WF5 'Check Follow-up' and the dashboard (shared/email/nilRules.js).
// o = { lang: 'tr' | 'en', calendarLink, ownDomain, senderName }. Returns a list of reasons (empty = passes).
function nilRuleIssues(text, o) {
  const t = String(text || '');
  const low = t.toLowerCase();
  const issues = [];
  const opt = o || {};
  const cal = String(opt.calendarLink || '').trim();
  const own = String(opt.ownDomain || 'texprove.com').toLowerCase();

  // Required: the 30-minute live demo and the calendar link (read from Settings 'Calendar Link').
  if (!/30[\s-]*(dakikalık|dakika|dk|minute|min)\b/i.test(t) || !/demo/i.test(t)) issues.push('30-minute demo offer missing');
  if (!cal) issues.push("Settings 'Calendar Link' is empty");
  else if (!t.includes(cal)) issues.push('Calendar link missing');

  // Links: only the calendar link and Texprove's own website.
  const links = t.match(/(https?:\/\/|www\.)[^\s)>\]]+/gi) || [];
  const foreign = links.filter(l => !(cal && l.startsWith(cal)) && !l.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').startsWith(own));
  if (foreign.length) issues.push('Link other than the calendar link and ' + own + ': ' + foreign.join(', '));

  // One offer only: the demo.
  if (/\b15[\s-]*(dakika|dk|min|minute)/i.test(t)) issues.push('Mentions 15 minutes (the offer is a 30-minute demo)');
  const offers = ['görüşme', 'toplantı', 'webinar', 'video', 'deneme sürümü', 'ücretsiz deneme', 'free trial', 'pilot'].filter(w => low.includes(w));
  if (/\b(call|meeting)\b/i.test(t)) offers.push('call/meeting');
  if (offers.length) issues.push('Offer other than the demo: ' + offers.join(', '));
  const promo = ['katalog', 'catalog', 'broşür', 'brochure', 'numune', 'paket', 'package', 'pricing', 'abonelik', 'subscription', 'lisans ücreti'].filter(w => low.includes(w));
  if (/\bsamples?\b/i.test(t)) promo.push('sample');
  if (promo.length) issues.push('Price, package, catalog or sample wording: ' + promo.join(', '));

  // Claims that must not be made.
  if (/\btier\b|tier[\s-]*\d/i.test(t)) issues.push('Mentions Tier (Tier-4 / tier depth claims are not allowed)');
  if (/%\s*\d|\d\s*%|yüzde\s+\d|\bpercent\b|\bper cent\b/i.test(t)) issues.push('Contains a percentage (no savings rates: there is no measured data)');
  if (/fewer audits|less audits|reduc\w*\s+(the\s+)?(number of\s+)?audits|daha az denetim|denetim(ler)?(in)?\s*(sayısı)?\w*\s*(azal|düş)/i.test(t)) issues.push('Claims fewer audits');
  const figures = ['rakip', 'competitor', 'araştırmaya göre', 'araştırmalara göre', 'according to a study', 'studies show', 'gartner', 'mckinsey'].filter(w => low.includes(w));
  if (figures.length) issues.push('Competitor or vendor figures: ' + figures.join(', '));

  // Regulatory dates: only 14 December 2027, "2027" (textile DPP, expected) and April 2028 (EPR).
  const months = 'ocak|şubat|mart|nisan|mayıs|haziran|temmuz|ağustos|eylül|ekim|kasım|aralık|january|february|march|april|may|june|july|august|september|october|november|december';
  const okDates = ['14 aralık 2027', '14 december 2027', 'nisan 2028', 'april 2028', '17 nisan 2028', '17 april 2028'];
  const badDates = [];
  for (const m of low.matchAll(new RegExp('(\\d{1,2}\\s+)?(' + months + ')\\s+(\\d{1,2},?\\s+)?(20\\d\\d)', 'g'))) {
    if (Number(m[4]) >= 2027 && !okDates.includes(m[0].replace(/\s+/g, ' ').trim())) badDates.push(m[0].trim());
  }
  for (const m of low.matchAll(/\b(20\d\d)\b/g)) {
    const y = Number(m[1]);
    if (y > 2028) badDates.push(m[1]);
    if (y === 2028 && !/(nisan|april)\s+$/.test(low.slice(Math.max(0, m.index - 8), m.index))) badDates.push('2028 without April');
  }
  if (badDates.length) issues.push('Date other than 14 December 2027, 2027 (expected) and April 2028: ' + [...new Set(badDates)].join(', '));

  // Language rule: Turkish for firms in Turkey, English abroad. Judged on the text above the signature.
  const lines = t.replace(/\r/g, '').split('\n');
  const iSig = opt.senderName ? lines.findIndex(l => l.trim() === String(opt.senderName).trim()) : -1;
  const main = ' ' + (iSig > 0 ? lines.slice(0, iSig) : lines).join(' ').toLowerCase().replace(/[.,;:!?()"']/g, ' ') + ' ';
  const count = (ws) => ws.reduce((n, w) => n + main.split(' ' + w + ' ').length - 1, 0);
  const tr = count(['ve', 'bir', 'için', 'ile', 'bu', 'sayın', 'size', 'sizin']);
  const en = count(['the', 'and', 'for', 'your', 'you', 'with', 'dear', 'is']);
  if (opt.lang === 'tr' && tr <= en) issues.push('Wrong language: firms in Turkey get Turkish');
  if (opt.lang === 'en' && en <= tr) issues.push('Wrong language: firms outside Turkey get English');
  return issues;
}

// Trade-secret rule (Nil's compliance plan): no buyer names, order volumes, prices, capacities or margins in outreach text.
// ownName: the recipient company's own name (a brand may be named in a mail to that brand).
function sensitiveIssues(text, ownName) {
  const t = String(text || '');
  const low = t.toLowerCase();
  const own = String(ownName || '').toLowerCase();
  const issues = [];
  const buyers = ['zara', 'inditex', 'h&m', 'hennes', 'primark', 'c&a', 'mango', 'marks & spencer', 'm&s', 'tesco', 'lidl', 'aldi', 'decathlon', 'hugo boss', 'adidas', 'puma', 'nike', 'esprit', 's.oliver', 'tom tailor', 'bestseller', 'zalando', 'about you', 'otto', 'benetton', 'diesel', "levi's", 'levis', 'kiabi', 'celio', 'promod', 'etam', 'carrefour', 'auchan', 'tchibo', 'takko', 'ernsting', 'peek & cloppenburg', 'hunkemöller', 'we fashion', 'jack & jones', 'vero moda', 'pepe jeans', 'desigual', 'el corte ingl', 'cortefiel', 'mayoral', 'g-star', 'scotch & soda', 'zeeman', 'matalan', 'river island', 'new look', 'boohoo', 'asos', 'sinsay', 'cropp', 'mohito', 'pull&bear', 'pull & bear', 'bershka', 'stradivarius', 'massimo dutti', 'oysho', 'ikea', 'jysk', 'armani', 'gucci', 'prada', 'burberry', 'ralph lauren', 'tommy hilfiger', 'calvin klein', 'uniqlo', 'lacoste', 'superdry', 'jd sports', 'intersport', 'engelbert strauss', 'koton', 'defacto', 'lc waikiki'];
  // Whole-word match only: "zara" must not fire inside "yazarak", nor "otto" inside "cotton".
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const wordHit = (name) => new RegExp('(^|[^a-z0-9çğıöşüâîû])' + esc(name) + '(?=$|[^a-z0-9çğıöşüâîû])').test(low);
  const named = buyers.filter(b => wordHit(b) && !(own && own.includes(b)));
  if (named.length) issues.push('Names a buyer or brand: ' + named.join(', '));
  if (/(€|£|₺|\$|\b(eur|usd|gbp|tl)\b)/i.test(t)) issues.push('Mentions money or prices');
  if (/\b\d[\d.,]*\s*(adet|parça|ton|tons|tonnes|kg|metre|meters|pcs|pieces|units|orders|order|sipariş)\b/i.test(t)) issues.push('Mentions order volumes or quantities');
  const words = ['sipariş hacmi', 'sipariş adedi', 'order volume', 'order quantity', 'minimum order', 'moq', 'fiyat', 'price', 'birim fiyat', 'tedarikçisi olduğunuz', 'supplier of', 'supplies to', 'supplier to', 'customer list', 'müşteri listesi', 'kapasite', 'capacity', 'marj', 'margin', 'ciro', 'revenue', 'turnover'];
  const hits = words.filter(w => low.includes(w));
  if (hits.length) issues.push('Commercially sensitive wording: ' + hits.join(', '));
  return issues;
}

// Builds the follow-up text from fixed parts (Nil's decisions of 23 Nov 2026, sections 10 and 15).
// Follow-up 1 uses Nil's four templates (exporter or brand, Turkish or English). For follow-ups 2 and 3, and for
// rewrites Nil asked for, only the middle paragraph comes from the model. Greeting, demo sentence, calendar link
// (Settings 'Calendar Link'), sign-off, signature and footer are always added here.
const lead = $('Loop Over Follow-ups').item.json;
const s = $('Read Settings (mail)').first().json || {};
const clean = (x) => String(x || '').replace(/[ \t]+/g, ' ').trim();
const lang = ['turkey', 'türkiye', 'turkiye'].includes(String(lead.Country || '').trim().toLowerCase()) ? 'tr' : 'en';
const brand = /^(marka|brand)$/i.test(String(lead.Segment || '').trim());
const cal = clean(s['Calendar Link']);
const n = Number(lead['Follow-up Count'] || 0) + 1;
const out = $input.item.json.output;
const llmMiddle = out && typeof out.middle === 'string' ? out.middle.trim() : '';

// Greeting: reuse the name from the first email's greeting line, in this mail's language.
const firstLine = String(lead['Draft Body'] || '').replace(/\r/g, '').split('\n').map(l => l.trim()).find(Boolean) || '';
const m = /^(?:Sayın|Dear)\s+(.+?)\s*,?$/.exec(firstLine);
let who = m ? m[1] : '';
const team = !who || /\s(ekibi|team)$/i.test(who);
if (team) who = clean(who.replace(/\s(ekibi|team)$/i, '')) || clean(lead.Company);
const greeting = lang === 'tr' ? 'Sayın ' + who + (team ? ' ekibi,' : ',') : 'Dear ' + who + (team ? ' team,' : ',');

const T = {
  exporter_tr: ["Geçen hafta gönderdiğim maile kısa bir ek yapmak istedim.", "AB'li müşterileriniz dijital ürün pasaportu ve uyum verisini giderek daha sık soracak: zorla çalıştırma yasağı 14 Aralık 2027'de uygulanmaya başlıyor, tekstil pasaportu düzenlemesi 2027'de bekleniyor. TexProve ile bu veriyi her müşteri için yeniden hazırlamak yerine bir kez düzenler, hepsine yeniden sunarsınız. ERP'niz değişmez; Excel veya API ile bağlanırsınız. Tedarikçi ağınızı açmanız gerekmez."],
  exporter_en: ["A short follow-up to my note last week.", "Your EU customers will ask for Digital Product Passport and compliance data more and more often: the forced labour ban applies from 14 December 2027, and the textile passport rules are expected in 2027. With TexProve you organise that data once and reuse it for every customer, instead of preparing it again each time. Your ERP stays as it is; you connect by Excel or API. You do not have to open up your supplier network."],
  brand_tr: ["Geçen hafta gönderdiğim maile kısa bir ek yapmak istedim.", "Tedarikçi verisinde işin en zor kısmı çoğu zaman tedarikçinin katılımıdır. TexProve'da tedarikçiniz ağını açmadan kanıtı paylaşır ve katılım onun için ücretsizdir. Size ulaşan her beyanın arkasında belge ve denetçi onayı bulunur. Zorla çalıştırma yasağı 14 Aralık 2027'de uygulanmaya başlıyor, tekstil pasaportu düzenlemesi 2027'de bekleniyor; ikisi de aynı veriyi istiyor."],
  brand_en: ["A short follow-up to my note last week.", "With supplier data, the hardest part is often getting suppliers to take part. On TexProve your supplier shares the evidence without opening up its network, and joining is free for them. Every claim that reaches you has a document and an auditor's approval behind it. The forced labour ban applies from 14 December 2027 and the textile passport rules are expected in 2027; both ask for the same data."],
};
const cta = lang === 'tr'
  ? 'Sizin sipariş akışınıza benzer bir örnek üzerinden 30 dakikalık canlı demo için size uygun zamanı buradan seçebilirsiniz: ' + cal
  : 'You can pick a time for a 30-minute live demo, built on an example close to your own order flow, here: ' + cal;
const middle = llmMiddle ? [llmMiddle] : (n === 1 ? T[(brand ? 'brand_' : 'exporter_') + lang] : []);
const sig = [s['Sender Name'], s['Sender Title'], s['Company Legal Name'], String(s['Company Address'] || '').trim(), s['Company Website'] || 'https://www.texprove.com'].map(x => String(x || '').trim()).filter(Boolean).join('\n');
const source = lang === 'tr' ? 'İletişim bilgilerinizi şirketinizin herkese açık web sitesinden aldık.' : "We found your contact details on your company's public website.";
const optOut = clean(lang === 'tr' ? s['Opt-out TR'] : s['Opt-out EN']);
const body = middle.length ? [greeting, ...middle, cta, lang === 'tr' ? 'Saygılarımla,' : 'Kind regards,', sig, source, optOut].filter(Boolean).join('\n\n') : '';
return { json: { ...$input.item.json, output: { body }, fu_lang: lang, fu_audience: brand ? 'brand' : 'exporter', fu_template: !llmMiddle && n === 1 } };

// Leads that only wait (draft waiting for approval, or approved but not due yet) are left out here, so they do not
// take one of the 15 daily slots. Order: approved and due (send), declined, then leads that need a draft.
const today = $today.toFormat('yyyy-MM-dd');
const ranked = [];
for (const item of $input.all()) {
  const j = item.json;
  const draft = String(j['Follow-up Draft'] || '').trim();
  const approved = String(j.Approved || '').trim();
  const due = String(j['Next Follow-up Date'] || '').slice(0, 10) <= today;
  let rank = -1;
  if (!draft || approved === 'Edit') rank = 2;
  else if (approved === 'Yes' && due) rank = 0;
  else if (approved === 'No') rank = 1;
  if (rank >= 0) ranked.push({ rank, item });
}
ranked.sort((a, b) => a.rank - b.rank);
return ranked.map(r => r.item);
